        if isinstance(obj, dict):
            new_dict = {}
            for k, v in obj.items():
                if v is None:
                    continue
                new_dict[k] = clean_data(v)
            return new_dict
        elif isinstance(obj, list):
            new_list = []
            for item in obj:
                if item is None:
                    continue
                new_list.append(clean_data(item))
            return new_list
        elif isinstance(obj, str):
            return re.sub(r'[\w\.-]+@[\w\.-]+', REPLACE_NONE, obj)
        else:
            return obj

    data = json.loads(json_str)
    processed = clean_data(data)

    def extract_values(obj):
        if isinstance(obj, dict):
            for v in obj.values():
                yield from extract_values(v)
        elif isinstance(obj, list):
            for item in obj:
                yield from extract_values(item)
        else:
            yield obj

    value_counts = Counter(extract_values(processed))
    return {"data": processed, "value_counts": value_counts}

import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    data = json.loads(json_str)
    email_pattern = re.compile(r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b')
    def process(obj):
        if isinstance(obj, dict):
            return {k: process(v) for k, v in obj.items() if v is not None}
        elif isinstance(obj, list):
            return [process(item) for item in obj if item is not None]
        elif isinstance(obj, str):
            return REPLACE_NONE if email_pattern.fullmatch(obj) else obj
        else:
            return obj
    processed = process(data)
    def collect_values(obj):
        if isinstance(obj, dict):
            for v in obj.values():
                yield from collect_values(v)
        elif isinstance(obj, list):
            for item in obj:
                yield from collect_values(item)
        else:
            yield obj
    value_counts = Counter(collect_values(processed))
    return {"data": processed, "value_counts": value_counts}

import numpy as np
from collections import defaultdict
import json
import csv

def task_func(input_file, output_file):
    with open(input_file, 'r') as f:
        data = json.load(f)

    stats = defaultdict(list)
    for entry in data:
        for key, value in entry.items():
            stats[key].append(value)

    result = {}
    for key, values in stats.items():
        result[key] = {
            'mean': np.mean(values),
            'median': np.median(values)
        }

    with open(output_file, 'w', newline='') as csvfile:
        writer = csv.writer(csvfile)
        writer.writerow(['key', 'mean', 'median'])
        for key, values in result.items():
            writer.writerow([key, values['mean'], values['median']])

    return result

